(()=>{const select=document.querySelector('.language');if(!select)return;select.addEventListener('change',e=>{const lang=e.target.value;const path=location.pathname;if(lang==='ar'){if(!path.startsWith('/ar/'))location.href='/ar'+(path==='/'?'/' : path);return}if(path.startsWith('/ar/')){const plain=path.slice(3)||'/';location.href=plain;return}localStorage.setItem('tivione-language',lang)})})();
